// The bundled core knowledge pack (docs/ARCHITECTURE.md §4, D-007).
// assets/pack/ is generated by `npm run sync:pack`; run it before building.

import type { SQLiteDatabase } from 'expo-sqlite';
import manifest from '../../assets/pack/manifest.json';

export const SUPPORTED_PACK_SCHEMA_VERSION = 1;

export const packManifest = manifest;

// The file name includes version and checksum, so a new pack in an app update is
// imported as a new file instead of being skipped because an older copy exists.
export const packDatabaseName = `core-${manifest.version}-${manifest.sha256.slice(0, 12)}.db`;

// eslint-disable-next-line @typescript-eslint/no-require-imports
export const packAsset: number = require('../../assets/pack/core.sqlite');

// Runs before any screen renders. Throws if the pack cannot be used on this device.
export async function verifyPack(db: SQLiteDatabase): Promise<void> {
  const schema = await db.getFirstAsync<{ value: string }>("SELECT value FROM meta WHERE key = 'schemaVersion'");
  if (Number(schema?.value) !== SUPPORTED_PACK_SCHEMA_VERSION) {
    throw new Error(`Unsupported pack schema version: ${schema?.value ?? 'missing'}`);
  }
  // Fails with "no such tokenizer" if this device's SQLite lacks FTS5 trigram support (D-018).
  await db.getFirstAsync('SELECT item_id FROM storage_search WHERE storage_search MATCH ? LIMIT 1', ['"kal"']);
}
